          "펭! 오늘 밤은 바람이 딱 좋아.\n남풍이야. 구름 한 점 없고, 달은 딱 반쯤.\n{name}, 등대 꼭대기까지 같이 올라갈래?\n약속했던 그 밤이 바로 오늘이야. 하루 종일 깃털이 들썩였어.",
