          "어젯밤엔 처음으로 불빛을 남쪽으로 안 돌렸어.\n렌즈 손잡이를 잡고 한참 망설이다가.\n대신 섬 쪽을 비췄어.\n불빛이 바다 대신 지붕들 위를 천천히 쓰다듬고 지나갔어. 하나하나, 잘 자라고 인사하듯이.",
